def maximum_parity_subsequence_score(nums,x):
    best=[float('-inf')]*2;best[nums[0]%2]=nums[0]
    for value in nums[1:]:
        parity=value%2;best[parity]=max(best[parity]+value,best[1-parity]+value-x)
    return max(best)

